import {sources,layers,nodes,edges,connectors,transducers,defaults,enabled,activeEdges,voltageDrop,networkStatus,powerState,cableSpec,minimumSection,modelNodes,hasNetwork,hasPlotter} from './data.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],byId=id=>modelNodes(config).find(n=>n.id===id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='bord-project-v1';
