$('#route').onchange=()=>{routeKey=$('#route').value;step=0;const r=routes()[routeKey];if(r&&routeSteps(r).length){switchLayer(r.layer);const item=routeSteps(r)[0];choose(item.type,item.id);if(routeKey==='bilge')toast('Prova AUTO, aigua a la sentina i general de serveis OFF.')}else{if(r){toast('Activa aquest equip a la configuració per seguir-ne el recorregut.');routeKey='';$('#route').value=''}draw();}};
for(const [id,delta]of [['previous',-1],['next',1]])$('#'+id).onclick=()=>{const r=routes()[routeKey];if(!r)return;step=Math.max(0,Math.min(routeSteps(r).length-1,step+delta));const item=routeSteps(r)[step];choose(item.type,item.id,true)};
