// Zoom: 1 és la mida de lectura (amplada mínima del CSS); «Ajusta» mostra tot l'esquema dins la finestra.
function readableWidth(){const box=$('#diagramScroll'),w=box?.clientWidth;if(!w)return 0;const min=parseFloat(globalThis.getComputedStyle?.(box).getPropertyValue('--diagram-min'))||0;return Math.max(w,min)}
function fitZoom(){const box=$('#diagramScroll'),R=readableWidth();if(!R)return 1;return Math.min(1,Math.min(box.clientWidth,(box.clientHeight-6)*sceneSize.w/sceneSize.h)/R)}
function applyZoom(){const R=readableWidth(),el=$('#diagram');if(!R){el.style.width=zoom*100+'%';return}el.style.width=Math.round(R*zoom)+'px';const fit=$('#zoomReset');if(fit)fit.setAttribute('aria-pressed',String(fitted))}
function setZoom(next,cx,cy,fit=false){fitted=fit;const box=$('#diagramScroll'),R=readableWidth();next=Math.max(Math.min(fitZoom(),1),Math.min(3,next));if(!R||!box.getBoundingClientRect){zoom=next;applyZoom();return}
 const rect=box.getBoundingClientRect();if(cx===undefined){cx=rect.left+box.clientWidth/2;cy=rect.top+box.clientHeight/2}
 const ox=cx-rect.left,oy=cy-rect.top,px=box.scrollLeft+ox,py=box.scrollTop+oy,ratio=next/zoom;zoom=next;applyZoom();box.scrollLeft=px*ratio-ox;box.scrollTop=py*ratio-oy}
// Porta l'element seleccionat a la vista de l'esquema si ha quedat fora.
function revealSelected(){const box=$('#diagramScroll');if(!box?.clientWidth||!lastScene)return;let x,y;
 if(selected.type==='node'){const n=lastScene.nodes.find(n=>n.id===selected.id);if(!n)return;x=n.x+n.width/2;y=n.y+n.height/2}else{const w=lastGeometry?.get(selected.id);if(!w)return;x=w.label.x;y=w.label.y}
 const k=$('#diagram').getBoundingClientRect().width/sceneSize.w,px=x*k,py=y*k,m=40;
 if(px<box.scrollLeft+m||px>box.scrollLeft+box.clientWidth-m||py<box.scrollTop+m||py>box.scrollTop+box.clientHeight-m)box.scrollTo?.({left:px-box.clientWidth/2,top:py-box.clientHeight/2,behavior:'smooth'})}
$('#zoomIn').onclick=()=>setZoom(zoom*1.25);$('#zoomOut').onclick=()=>setZoom(zoom*.8);
$('#zoomReset').onclick=()=>fitted?setZoom(1):setZoom(fitZoom(),undefined,undefined,true);
(()=>{const box=$('#diagramScroll');if(!box?.addEventListener||typeof PointerEvent==='undefined')return;
 // Ctrl/⌘ + roda, i el pessic del trackpad (que arriba com a roda amb Ctrl).
 box.addEventListener('wheel',e=>{if(!e.ctrlKey&&!e.metaKey)return;e.preventDefault();setZoom(zoom*Math.exp(-e.deltaY*.0025),e.clientX,e.clientY)},{passive:false});
 // Arrossega amb el ratolí per moure l'esquema; un clic després d'arrossegar no selecciona res.
 let drag=null,moved=false;
 box.addEventListener('pointerdown',e=>{if(e.pointerType!=='mouse'||e.button!==0)return;drag={x:e.clientX,y:e.clientY,left:box.scrollLeft,top:box.scrollTop};moved=false});
 addEventListener('pointermove',e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(!moved&&Math.hypot(dx,dy)<5)return;moved=true;box.classList.add('panning');box.scrollLeft=drag.left-dx;box.scrollTop=drag.top-dy});
 addEventListener('pointerup',()=>{drag=null;box.classList.remove('panning')});
 box.addEventListener('click',e=>{if(moved){e.stopPropagation();e.preventDefault();moved=false}},true);
 box.addEventListener('dblclick',e=>{if(e.target.closest?.('.node,.edge'))return;setZoom(zoom<1.6?zoom*1.8:fitZoom(),e.clientX,e.clientY)});
 // Pessic amb dos dits: el desplaçament amb un dit continua sent natiu.
 let pinch=null;const span=t=>Math.hypot(t[0].clientX-t[1].clientX,t[0].clientY-t[1].clientY);
 box.addEventListener('touchstart',e=>{if(e.touches.length===2)pinch={d:span(e.touches),z:zoom}},{passive:true});
 box.addEventListener('touchmove',e=>{if(!pinch||e.touches.length!==2)return;e.preventDefault();const t=e.touches;setZoom(pinch.z*span(t)/pinch.d,(t[0].clientX+t[1].clientX)/2,(t[0].clientY+t[1].clientY)/2)},{passive:false});
 box.addEventListener('touchend',e=>{if(e.touches.length<2)pinch=null});
 let width=box.clientWidth;addEventListener('resize',()=>{if(box.clientWidth!==width){width=box.clientWidth;fitted?setZoom(fitZoom(),undefined,undefined,true):setZoom(zoom)}});
})();
