// Calcula en segon pla el traçat de les altres xarxes: el de 12 V pot trigar més d'un segon en un mòbil.
function prewarm(){if(typeof Worker==='undefined')return;let worker;try{worker=new Worker('./route-worker.js',{type:'module'})}catch{return}
 const jobs=[];const current=layer;
 for(const l of Object.keys(layers)){if(l===current)continue;layer=l;const es=activeEdges(config,l).filter(e=>$('#returns').checked||e.type!=='negative'),key=l+':'+es.map(e=>e.id).join(',');if(!geometryCache.has(key))jobs.push({key,scene:layoutDiagram(visibleNodes()),edges:JSON.parse(JSON.stringify(es))})}
 layer=current;if(!jobs.length){worker.terminate();return}
 let pending=jobs.length;worker.onmessage=e=>{if(!geometryCache.has(e.data.key))geometryCache.set(e.data.key,e.data.geometry);if(--pending===0)worker.terminate()};worker.onerror=()=>worker.terminate();
 for(const job of jobs)worker.postMessage(job)}
setTimeout(prewarm,800);
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js',{updateViaCache:'none'}).then(async reg=>{registration=reg;const ready=await navigator.serviceWorker.ready;const check=()=>{const worker=navigator.serviceWorker.controller||ready.active;if(worker)worker.postMessage('VERIFY_OFFLINE')};navigator.serviceWorker.addEventListener('message',event=>{if(event.data==='OFFLINE_READY')$('#offline').textContent='● Disponible fora de línia'});navigator.serviceWorker.addEventListener('controllerchange',check);check();reg.update().catch(()=>{});}).catch(()=>$('#offline').textContent='Fora de línia: cal HTTPS o localhost')}else $('#offline').textContent='Navegador sense suport PWA';
